def original_measurement_bytes():
    raw = zlib.decompress(base64.b85decode(_MEASUREMENT_B85))
    if hashlib.sha256(raw).hexdigest() != MEASUREMENT_SHA256:
        raise ValueError('Original native readback bytes changed')
    return raw


def original_shared_preparation_sources():
    raw = base64.b64decode(_SHARED_B64)
    if hashlib.sha256(raw).hexdigest() != _SHARED_SHA256:
        raise ValueError('Original shared preparer source changed')
    return {_SHARED_RELATIVE: raw}

